package com.danawa.search.analysis.dict;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.File;
import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.regex.Pattern;
import java.util.Set;

import com.danawa.io.DataInput;
import com.danawa.io.DataOutput;
import com.danawa.io.InputStreamDataInput;
import com.danawa.io.OutputStreamDataOutput;
import com.danawa.util.CharVector;

public class SpaceDictionary extends MapDictionary {

	private final static String DELIMITER = "\\s";
	private static final Pattern ptn = Pattern.compile("^[\\x00-\\x7F]*$");
	private Set<CharSequence> wordSet;

	public SpaceDictionary() {
		this(false);
	}

	public SpaceDictionary(boolean ignoreCase) {
		super(ignoreCase);
		if (wordSet == null) {
			wordSet = new HashSet<>();
		}
	}

	public SpaceDictionary(File file, boolean ignoreCase, String label, int seq, String tokenType, ProductNameDictionary.Type type) {
		super(file, ignoreCase, label, seq, tokenType, type);
	}

	public SpaceDictionary(InputStream is, boolean ignoreCase, String label, int seq, String tokenType, ProductNameDictionary.Type type) {
		super(is, ignoreCase, label, seq, tokenType, type);
	}

	public Set<CharSequence> getWordSet() {
		return wordSet;
	}

	public void setWordSet(Set<CharSequence> wordSet) {
		this.wordSet = wordSet;
	}

	public Set<CharSequence> getUnmodifiableWordSet() {
		return Collections.unmodifiableSet(wordSet);
	}

	@Override
	public void addEntry(CharSequence word, Object[] values, List<Object> columnList) {
		if (values == null || values.length == 0) { return; }
		String keyword = String.valueOf(values[0]).replaceAll(DELIMITER, "");
		wordSet.add(new CharVector(String.valueOf(keyword), ignoreCase));
		String[] list = String.valueOf(values[0]).split(DELIMITER);
		super.addEntry(keyword, list, columnList);
		for (int i = 0; i < list.length; i++) {
			String str = list[i].trim();
			// ASCII 골라내기
			if (!ptn.matcher(str).find()) {
				wordSet.add(new CharVector(String.valueOf(list[i]).trim(), ignoreCase));
			}
		}
	}

	@Override
	@SuppressWarnings("resource")
	public void writeTo(OutputStream out) throws IOException {
		if (!(out instanceof BufferedOutputStream)) {
			try { out = new BufferedOutputStream(out); } catch (Exception ignore) { }
		}
		super.writeTo(out);
		DataOutput output = new OutputStreamDataOutput(out);
		// write size of synonyms
		output.writeVInt(wordSet.size());

		// write synonyms
		Iterator<CharSequence> synonymIter = wordSet.iterator();
		for (; synonymIter.hasNext();) {
			CharVector value = CharVector.valueOf(synonymIter.next());
			output.writeUString(value.array(), value.offset(), value.length());
		}
		try { out.flush(); } catch (Exception ignore) { }
	}

	@Override
	@SuppressWarnings("resource")
	public void readFrom(InputStream in) throws IOException {
		if (!(in instanceof BufferedInputStream)) {
			try { in = new BufferedInputStream(in); } catch (Exception ignore) { }
		}
		super.readFrom(in);
		DataInput input = new InputStreamDataInput(in);
		wordSet = new HashSet<>();
		int size = input.readVInt();
		for (int entryInx = 0; entryInx < size; entryInx++) {
			wordSet.add(new CharVector(input.readUString(), ignoreCase));
		}
	}

	@Override
	public void reload(Object object) throws IllegalArgumentException {
		if (object != null && object instanceof SpaceDictionary) {
			super.reload(object);
			SpaceDictionary spaceDictionary = (SpaceDictionary) object;
			this.wordSet = spaceDictionary.getWordSet();
		} else {
			throw new IllegalArgumentException("Reload dictionary argument error. argument = " + object);
		}
	}
}

package com.cowave.search.utils

import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.io.InputStream
import java.io.OutputStream

/**
 * SET 타입 사전 직렬화/역직렬화
 *
 * 바이너리 형식:
 * - Int: 엔트리 개수
 * - String[]: 각 단어 (UString 형식)
 */
object SetDictionarySerializer {
    fun writeTo(
        data: SetDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // write size
            output.writeInt(data.words.size)

            // write each word
            for (word in data.words) {
                output.writeString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: SetDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): SetDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val size = input.readInt()
            val words = mutableSetOf<String>()

            repeat(size) {
                val word = input.readString()
                words.add(if (ignoreCase) word.uppercase() else word)
            }

            return SetDictionaryData(words, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): SetDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * MAP 타입 사전 직렬화/역직렬화
 *
 * 바이너리 형식:
 * - VInt: 맵 크기
 * - 각 엔트리:
 *   - UString: 키
 *   - VInt: 값 배열 크기
 *   - UString[]: 값들
 */
object MapDictionarySerializer {
    fun writeTo(
        data: MapDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            writeMapData(output, data.entries)
            output.flush()
        }
    }

    internal fun writeMapData(
        output: BinaryDataOutput,
        entries: Map<String, List<String>>,
    ) {
        // write map size
        output.writeVInt(entries.size)

        // write each entry
        for ((key, values) in entries) {
            // write key
            output.writeUString(key)

            // write values
            output.writeVInt(values.size)
            for (value in values) {
                output.writeUString(value)
            }
        }
    }

    fun writeTo(
        data: MapDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): MapDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val entries = readMapData(input, ignoreCase)
            return MapDictionaryData(entries, ignoreCase)
        }
    }

    internal fun readMapData(
        input: BinaryDataInput,
        ignoreCase: Boolean,
    ): Map<String, List<String>> {
        val size = input.readVInt()
        val entries = mutableMapOf<String, List<String>>()

        repeat(size) {
            val key =
                input.readString().let {
                    if (ignoreCase) it.uppercase() else it
                }

            val valueLength = input.readVInt()
            val values = mutableListOf<String>()

            repeat(valueLength) {
                val value =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                values.add(value)
            }

            entries[key] = values
        }

        return entries
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): MapDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * SYNONYM 타입 사전 직렬화/역직렬화
 * MapDictionary 형식 + wordSet
 *
 * 바이너리 형식:
 * - [MapDictionary 형식] (synonymMap)
 * - VInt: wordSet 크기
 * - UString[]: 모든 동의어 단어들
 */
object SynonymDictionarySerializer {
    fun writeTo(
        data: SynonymDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // 1. MapDictionary 형식으로 synonymMap 저장
            MapDictionarySerializer.writeMapData(output, data.synonymMap)

            // 2. wordSet 저장
            output.writeVInt(data.wordSet.size)
            for (word in data.wordSet) {
                output.writeUString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: SynonymDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): SynonymDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            // 1. synonymMap 읽기
            val synonymMap = MapDictionarySerializer.readMapData(input, ignoreCase)

            // 2. wordSet 읽기
            val wordSetSize = input.readVInt()
            val wordSet = mutableSetOf<String>()
            repeat(wordSetSize) {
                val word =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                wordSet.add(word)
            }

            return SynonymDictionaryData(synonymMap, wordSet, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): SynonymDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * SPACE 타입 사전 직렬화/역직렬화
 * MapDictionary 형식 + wordSet
 *
 * 바이너리 형식:
 * - [MapDictionary 형식] (spaceMap)
 * - VInt: wordSet 크기
 * - UString[]: 모든 단어들
 */
object SpaceDictionarySerializer {
    fun writeTo(
        data: SpaceDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // 1. MapDictionary 형식으로 spaceMap 저장
            MapDictionarySerializer.writeMapData(output, data.spaceMap)

            // 2. wordSet 저장
            output.writeVInt(data.wordSet.size)
            for (word in data.wordSet) {
                output.writeUString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: SpaceDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): SpaceDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            // 1. spaceMap 읽기
            val spaceMap = MapDictionarySerializer.readMapData(input, ignoreCase)

            // 2. wordSet 읽기
            val wordSetSize = input.readVInt()
            val wordSet = mutableSetOf<String>()
            repeat(wordSetSize) {
                val word =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                wordSet.add(word)
            }

            return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): SpaceDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * COMPOUND 타입 사전 직렬화/역직렬화
 * MapDictionary 형식 + mainWordSet + wordSet
 *
 * 바이너리 형식:
 * - [MapDictionary 형식] (compoundMap)
 * - VInt: mainWordSet 크기
 * - UString[]: 메인 키워드들
 * - VInt: wordSet 크기
 * - UString[]: 모든 분해 단어들
 */
object CompoundDictionarySerializer {
    fun writeTo(
        data: CompoundDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // 1. MapDictionary 형식으로 compoundMap 저장
            MapDictionarySerializer.writeMapData(output, data.compoundMap)

            // 2. mainWordSet 저장
            output.writeVInt(data.mainWordSet.size)
            for (word in data.mainWordSet) {
                output.writeUString(word)
            }

            // 3. wordSet 저장
            output.writeVInt(data.wordSet.size)
            for (word in data.wordSet) {
                output.writeUString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: CompoundDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): CompoundDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            // 1. compoundMap 읽기
            val compoundMap = MapDictionarySerializer.readMapData(input, ignoreCase)

            // 2. mainWordSet 읽기
            val mainWordSetSize = input.readVInt()
            val mainWordSet = mutableSetOf<String>()
            repeat(mainWordSetSize) {
                val word =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                mainWordSet.add(word)
            }

            // 3. wordSet 읽기
            val wordSetSize = input.readVInt()
            val wordSet = mutableSetOf<String>()
            repeat(wordSetSize) {
                val word =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                wordSet.add(word)
            }

            return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): CompoundDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * CUSTOM 타입 사전 직렬화/역직렬화
 * 다형적 값 타입 지원 (타입 마커 사용)
 *
 * 바이너리 형식:
 * - VInt: 맵 크기
 * - 각 엔트리:
 *   - UString: 키
 *   - VInt: 값 배열 크기
 *   - 각 값:
 *     - Byte: 타입 (1=Single, 2=Array)
 *     - 타입에 따른 데이터
 * - VInt: wordSet 크기
 * - UString[]: 모든 단어들
 */
object CustomDictionarySerializer {
    private const val TYPE_SINGLE = 1
    private const val TYPE_ARRAY = 2

    fun writeTo(
        data: CustomDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // 1. customMap 저장
            output.writeVInt(data.customMap.size)

            for ((key, values) in data.customMap) {
                // write key
                output.writeUString(key)

                // write values
                output.writeVInt(values.size)
                for (value in values) {
                    when (value) {
                        is CustomValue.Single -> {
                            output.writeByte(TYPE_SINGLE)
                            output.writeUString(value.value)
                        }

                        is CustomValue.Array -> {
                            output.writeByte(TYPE_ARRAY)
                            output.writeVInt(value.values.size)
                            for (v in value.values) {
                                output.writeUString(v)
                            }
                        }
                    }
                }
            }

            // 2. wordSet 저장
            output.writeVInt(data.wordSet.size)
            for (word in data.wordSet) {
                output.writeUString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: CustomDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): CustomDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            // 1. customMap 읽기
            val mapSize = input.readVInt()
            val customMap = mutableMapOf<String, List<CustomValue>>()

            repeat(mapSize) {
                val key =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }

                val valueLength = input.readVInt()
                val values = mutableListOf<CustomValue>()

                repeat(valueLength) {
                    val type = input.readByte()
                    val customValue =
                        when (type) {
                            TYPE_SINGLE -> {
                                val v =
                                    input.readString().let {
                                        if (ignoreCase) it.uppercase() else it
                                    }
                                CustomValue.Single(v)
                            }

                            TYPE_ARRAY -> {
                                val len = input.readVInt()
                                val arr = mutableListOf<String>()
                                repeat(len) {
                                    val v =
                                        input.readString().let {
                                            if (ignoreCase) it.uppercase() else it
                                        }
                                    arr.add(v)
                                }
                                CustomValue.Array(arr)
                            }

                            else -> {
                                throw IOException("Unknown custom value type: $type")
                            }
                        }
                    values.add(customValue)
                }

                customMap[key] = values
            }

            // 2. wordSet 읽기
            val wordSetSize = input.readVInt()
            val wordSet = mutableSetOf<String>()
            repeat(wordSetSize) {
                val word =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                wordSet.add(word)
            }

            return CustomDictionaryData(customMap, wordSet, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): CustomDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * TAG_PROB 타입 사전 직렬화/역직렬화
 * 형태소 품사 태그 확률 정보
 *
 * 바이너리 형식:
 * - Int: 맵 크기
 * - 각 엔트리:
 *   - String: 키 (단어)
 *   - Int: TagProb 목록 크기
 *   - 각 TagProb:
 *     - String: posTag
 *     - Double: probability
 */
object TagProbDictionarySerializer {
    fun writeTo(
        data: TagProbDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // write map size
            output.writeInt(data.probMap.size)

            for ((key, tagProbs) in data.probMap) {
                // write key
                output.writeString(key)

                // write tag probs
                output.writeInt(tagProbs.size)
                for (tagProb in tagProbs) {
                    output.writeString(tagProb.posTag)
                    output.writeDouble(tagProb.probability)
                }
            }

            output.flush()
        }
    }

    fun writeTo(
        data: TagProbDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): TagProbDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val size = input.readInt()
            val probMap = mutableMapOf<String, List<TagProb>>()

            repeat(size) {
                val key =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }

                val probLength = input.readInt()
                val tagProbs = mutableListOf<TagProb>()

                repeat(probLength) {
                    val posTag = input.readString()
                    val probability = input.readDouble()
                    tagProbs.add(TagProb(posTag, probability))
                }

                probMap[key] = tagProbs
            }

            return TagProbDictionaryData(probMap, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): TagProbDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

package com.cowave.search.utils

import com.cowave.search.config.DictionaryConfig
import com.cowave.search.domain.Type
import org.springframework.stereotype.Component
import java.io.File

/**
 * 사전 바이너리 컴파일러
 * ES 인덱스에서 읽은 사전 데이터를 바이너리 파일로 컴파일
 *
 * 기존 Java analysis-product의 사전 바이너리 형식과 100% 호환
 */
@Component
class DictionaryBinaryCompile(
    private val dictionaryConfig: DictionaryConfig,
) {
    /**
     * 설정된 출력 경로 반환
     */
    fun getOutputPath(): String = dictionaryConfig.outputPath

    /**
     * Type에 따른 출력 파일 경로 반환 (설정된 경로 사용)
     */
    fun getOutputFile(type: Type): File = File(dictionaryConfig.outputPath, getOutputFileName(type))

    /**
     * ES에서 조회한 Dictionary 목록을 설정된 경로에 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 생성된 파일
     */
    fun compileToConfiguredPath(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        ignoreCase: Boolean = true,
    ): File {
        val outputFile = getOutputFile(type)
        compileFromDictionaries(dictionaries, type, outputFile, ignoreCase)
        return outputFile
    }

    /**
     * 설정된 경로에서 사전 파일 로드
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 로드된 사전 데이터
     */
    fun loadFromConfiguredPath(
        type: Type,
        ignoreCase: Boolean = true,
    ): Any = load(type, getOutputFile(type), ignoreCase)

    /**
     * 기존 Type enum과 매핑하여 사전 컴파일
     * SET 타입: STOP, UNIT, USER, ENGLISH
     * SYNONYM 타입: SYNONYM, UNIT_SYNONYM
     * SPACE 타입: SPACE
     * COMPOUND 타입: COMPOUND
     */
    fun compile(
        type: Type,
        data: Any,
        outputFile: File,
    ) {
        outputFile.parentFile?.mkdirs()

        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.writeTo(data as SetDictionaryData, outputFile)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.writeTo(data as SynonymDictionaryData, outputFile)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.writeTo(data as SpaceDictionaryData, outputFile)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.writeTo(data as CompoundDictionaryData, outputFile)
            }
        }
    }

    /**
     * 바이너리 사전 파일을 읽어서 데이터 객체로 반환
     */
    fun load(
        type: Type,
        inputFile: File,
        ignoreCase: Boolean = true,
    ): Any =
        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.readFrom(inputFile, ignoreCase)
            }
        }

    /**
     * ES에서 조회한 Dictionary 목록을 타입별로 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param outputFile 출력 파일
     * @param ignoreCase 대소문자 무시 여부
     */
    fun compileFromDictionaries(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        outputFile: File,
        ignoreCase: Boolean = true,
    ) {
        val data =
            when (type) {
                Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                    // SET 타입: keyword만 사용
                    val words =
                        dictionaries
                            .mapNotNull { it.first?.trim() }
                            .filter { it.isNotEmpty() }
                            .toSet()
                    SetDictionaryData(words, ignoreCase)
                }

                Type.SYNONYM, Type.UNIT_SYNONYM -> {
                    // SYNONYM 타입: keyword -> value 매핑
                    createSynonymFromPairs(dictionaries, ignoreCase)
                }

                Type.SPACE -> {
                    // SPACE 타입: keyword -> value (공백 분리)
                    createSpaceFromPairs(dictionaries, ignoreCase)
                }

                Type.COMPOUND -> {
                    // COMPOUND 타입: keyword -> value (복합어 분해)
                    createCompoundFromPairs(dictionaries, ignoreCase)
                }
            }
        compile(type, data, outputFile)
    }

    /**
     * SET 타입 사전 생성
     */
    fun createSetDictionary(
        words: Collection<String>,
        ignoreCase: Boolean = true,
    ): SetDictionaryData = SetDictionaryData(words.toSet(), ignoreCase)

    /**
     * SYNONYM 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createSynonymFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SynonymDictionaryData {
        val synonymMap = mutableMapOf<String, MutableList<String>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (value.isNullOrBlank()) continue

            val synonyms = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            if (!keyword.isNullOrBlank()) {
                // 단방향: keyword -> synonyms
                val key = keyword.trim()
                synonymMap.getOrPut(key) { mutableListOf() }.addAll(synonyms)
                wordSet.add(key)
                wordSet.addAll(synonyms)
            } else {
                // 양방향: 모든 단어가 서로 동의어
                for (word in synonyms) {
                    val others = synonyms.filter { it != word }
                    synonymMap.getOrPut(word) { mutableListOf() }.addAll(others)
                }
                wordSet.addAll(synonyms)
            }
        }

        return SynonymDictionaryData(synonymMap, wordSet, ignoreCase)
    }

    /**
     * SPACE 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createSpaceFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SpaceDictionaryData {
        val spaceMap = mutableMapOf<String, List<String>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val splitWords =
                value
                    .split(",", " ")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            spaceMap[key] = splitWords
            wordSet.add(key)
            wordSet.addAll(splitWords)
        }

        return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
    }

    /**
     * COMPOUND 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createCompoundFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CompoundDictionaryData {
        val compoundMap = mutableMapOf<String, List<String>>()
        val mainWordSet = mutableSetOf<String>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val parts =
                value
                    .split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            compoundMap[key] = parts
            mainWordSet.add(key)
            wordSet.addAll(parts)
        }

        return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
    }

    /**
     * Type에 따른 출력 파일명 생성
     */
    fun getOutputFileName(type: Type): String =
        when (type) {
            Type.STOP -> "stop.dict"
            Type.UNIT -> "unit.dict"
            Type.USER -> "user.dict"
            Type.ENGLISH -> "english.dict"
            Type.SYNONYM -> "synonym.dict"
            Type.UNIT_SYNONYM -> "unit_synonym.dict"
            Type.SPACE -> "space.dict"
            Type.COMPOUND -> "compound.dict"
        }
}

