            ((readByte() and 0xFF) shl 8) or
            (readByte() and 0xFF)

    fun readShort(): Int = ((readByte() and 0xFF) shl 8) or (readByte() and 0xFF)

    fun readVInt(): Int {
        var b = readByte()
        if (b >= 0) return b

        var i = b and 0x7F
        b = readByte()
        i = i or ((b and 0x7F) shl 7)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F) shl 14)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F) shl 21)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x0F) shl 28)
        if ((b and 0xF0) == 0) return i

        throw IOException("Invalid vInt detected (too many bits)")
    }

    fun readLong(): Long = (readInt().toLong() shl 32) or (readInt().toLong() and 0xFFFFFFFFL)

    fun readVLong(): Long {
        var b = readByte()
        if (b >= 0) return b.toLong()

        var i = (b and 0x7F).toLong()
        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 7)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 14)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 21)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 28)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 35)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 42)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 49)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 56)
        if (b >= 0) return i

        throw IOException("Invalid vLong detected")
    }

    fun readFloat(): Float = java.lang.Float.intBitsToFloat(readInt())

    fun readDouble(): Double = java.lang.Double.longBitsToDouble(readLong())

    fun readBoolean(): Boolean = readByte() != 0

    fun readUString(): CharArray {
        val byteSize = readVInt()
        val chars = CharArray(byteSize / 2)
        for (i in chars.indices) {
            chars[i] = readShort().toChar()
        }
        return chars
    }

    fun readString(): String = String(readUString())

    fun readAString(): CharArray {
        val len = readVInt()
        val chars = CharArray(len)
        for (i in 0 until len) {
            chars[i] = readByte().toChar()
        }
        return chars
    }

    override fun close() {
        buffered.close()
    }
}

